import re


def parse_duration(s: str) -> int:
    """Parse a duration string like '1h30m', '45s', or '2h' into total seconds."""
    matches = re.findall(r'(\d+)([hms])', s)

    if not matches:
        raise ValueError(f"Invalid duration string: {s!r}")

    # Ensure the entire string is accounted for (no stray characters)
    reconstructed = ''.join(f'{num}{unit}' for num, unit in matches)
    if reconstructed != s:
        raise ValueError(f"Invalid duration string: {s!r}")

    total = 0
    for num, unit in matches:
        value = int(num)
        if unit == 'h':
            total += value * 3600
        elif unit == 'm':
            total += value * 60
        elif unit == 's':
            total += value

    return total
